model CreateUserRequest {
    name: String
    email: String
    age: Int
}

@table("users")
class UserEntity {
    id: String
    name: String
    createdAt: Int
}

class UserService {
    repo: UserRepository

    init(repo: UserRepository) {
        this.repo = repo
    }

    fn findById(id: String) -> User? {
        return this.repo.findById(id)
    }
}

interface UserRepository {
    fn findById(id: String) -> User?
    fn save(user: User) -> Bool
}
